async function prepareSignPlacement(file){if(!file||current?.id!=='sign')return;if(signState.preparing)return;if(signState.id&&signState.file===file){renderSignPlacement();return;}resetSignPlacement();signState.preparing=true;signState.file=file;cleanupPreview();id('filePreview').hidden=false;id('filePreview').innerHTML='<div class="sign-placement-loading">Preparing signature placement…</div>';try{const fd=new FormData();fd.append('file',file,file.name);const r=await fetch('/api/editor/prepare',{method:'POST',body:fd});let data=null;try{data=await r.json();}catch{}if(!r.ok)throw new Error(data?.error||`Could not preview PDF (${r.status}).`);signState.id=data.editor_id;signState.pages=data.pages||[];signState.page=0;const page=signState.pages[0];if(page){const st=standaloneSignatureSettings();const sig=signatureDataURL(st.text||'Signature',st.style,st.color);const baseW=32;const h=Math.max(5,Math.min(18,baseW*(page.width/page.height)/sig.ratio));signState.rect={x:Math.max(2,96-baseW),y:Math.max(2,94-h),w:baseW,h};}renderSignPlacement();}catch(err){id('filePreview').innerHTML=`<div class="error-box sign-placement-error">${esc(err.message||'Could not prepare signature placement.')}</div>`;}finally{signState.preparing=false;}}
