 id('settingsFields').innerHTML=t.id==='edit'?'':t.options.map(o=>fieldHTML(o)).join('');if(t.id==='sign')enhanceStandaloneSignSettings();id('workspaceNote').hidden=!t.note;id('workspaceNote').textContent=t.note||'';
