function resetEditor(){signaturePlacement=null;closeSignatureMaker();editorState={id:null,name:'',pages:[],page:0,actions:[],mode:'select',selectedSpan:null,selectedAction:null,pendingImage:null,preparing:false,zoom:100};editorPendingFile=null;const preview=id('filePreview');if(preview)preview.classList.remove('editor-active');id('workspaceView')?.classList.remove('editor-loaded');}

const EDITOR_PX_PER_PT=96/72;
function editorSettingsHTML(){return '';}
function editorVal(name,fallback=''){const el=id(name);return el?el.value:fallback;}
function editorCurrentPage(){return editorState.pages[editorState.page]||null;}
function editorRectStyle(rect,p){const [x0,y0,x1,y1]=rect;return `left:${x0/p.width*100}%;top:${y0/p.height*100}%;width:${Math.max(0,(x1-x0)/p.width*100)}%;height:${Math.max(0,(y1-y0)/p.height*100)}%;`;}
function editorCssFont(font=''){const f=String(font).toLowerCase();if(f.includes('times'))return `'Times New Roman',serif`;if(f.includes('courier'))return `'Courier New',monospace`;return `Arial,'Helvetica Neue',sans-serif`;}
function editorFontFlags(font=''){const f=String(font).toLowerCase();return {bold:/bold|black|demi/.test(f),italic:/italic|oblique/.test(f)};}
function editorFontName(font='Helvetica',bold=false,italic=false){const f=String(font).toLowerCase();const family=/times|serif/.test(f)?'Times':/courier|mono/.test(f)?'Courier':'Helvetica';return family+(bold&&italic?'-BoldItalic':bold?'-Bold':italic?'-Italic':'');}
function editorTextAction(index){const key=`${editorState.page}:${index}`;return editorState.actions.find(a=>a.type==='replace_text'&&a.spanKey===key)||null;}
function editorSpanHTML(sp,index,p){const action=editorTextAction(index);const selected=editorState.selectedSpan&&editorState.selectedSpan.page===editorState.page&&editorState.selectedSpan.index===index;const value=action?action.text:sp.text;const size=Number(action?.size||sp.size||12)*EDITOR_PX_PER_PT;const color=action?.color||sp.color||'#111111';const font=action?.font||sp.font||'Helvetica';const flags=editorFontFlags(font);const editable=editorState.mode==='select';return `<div class="editor-extracted-text ${selected?'selected':''} ${action?'changed':''}" data-editor-span="${index}" data-editor-color="${esc(color)}" contenteditable="${editable?'true':'false'}" spellcheck="false" style="${editorRectStyle(sp.bbox,p)};font-size:${Math.max(6,size)}px;--editor-text-color:${esc(color)};font-family:${editorCssFont(font)};font-weight:${flags.bold?700:400};font-style:${flags.italic?'italic':'normal'}">${esc(value)}</div>`;}
function editorActionHTML(action,p,index){if(action.page!==editorState.page)return '';const style=action.rect?editorRectStyle(action.rect,p):'';const color=esc(action.color||'#111111');const size=Math.max(7,Number(action.size||12)*EDITOR_PX_PER_PT);const selected=editorState.selectedAction===index;
 if(action.type==='replace_text')return '';
 if(action.type==='add_text'){const flags=editorFontFlags(action.font);return `<div class="editor-new-text ${selected?'selected':''}" data-editor-action="${index}" contenteditable="${editorState.mode==='select'?'true':'false'}" spellcheck="false" style="${style};font-size:${Math.max(7,Number(action.size||14)*EDITOR_PX_PER_PT)}px;color:${color};font-family:${editorCssFont(action.font)};font-weight:${flags.bold?700:400};font-style:${flags.italic?'italic':'normal'}">${esc(action.text||'')}</div>`;}
 if(action.type==='signature')return `<div class="editor-overlay editor-added-text signature" style="${style};font-size:${Math.max(7,Number(action.size||18)*EDITOR_PX_PER_PT)}px;color:${color}">${esc(action.text||'')}</div>`;
 if(action.type==='whiteout')return `<div class="editor-overlay editor-whiteout ${selected?'selected':''}" style="${style}"></div>`;
 if(action.type==='redact')return `<div class="editor-overlay editor-redact ${selected?'selected':''}" style="${style}"></div>`;
 if(action.type==='highlight')return `<div class="editor-overlay editor-highlight ${selected?'selected':''}" style="${style}"></div>`;
 if(action.type==='rectangle')return `<div class="editor-overlay editor-rectangle ${selected?'selected':''}" style="${style};border-color:${color};border-width:${Math.max(1,Number(action.width||2))}px"></div>`;
 if(action.type==='ellipse')return `<div class="editor-overlay editor-ellipse ${selected?'selected':''}" style="${style};border-color:${color};border-width:${Math.max(1,Number(action.width||2))}px"></div>`;
 if(action.type==='image')return `<img class="editor-overlay editor-image" alt="Inserted image" src="${esc(action.data||'')}" style="${style}">`;
 if(action.type==='draw'){const pts=(action.points||[]).map(pt=>`${Number(pt[0]).toFixed(1)},${Number(pt[1]).toFixed(1)}`).join(' ');return `<svg class="editor-drawing" viewBox="0 0 ${p.width} ${p.height}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="${Math.max(.5,Number(action.width||2))}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}return '';}
function editorSelectedData(){const sel=editorState.selectedSpan;if(!sel||sel.page!==editorState.page)return null;const p=editorCurrentPage(),sp=p?.text?.[sel.index];if(!sp)return null;const key=`${sel.page}:${sel.index}`;const action=editorTextAction(sel.index);return {sel,sp,key,action};}
function selectedTextStyle(){const data=editorSelectedData();if(data)return {size:Number(data.action?.size||data.sp.size||12),color:data.action?.color||data.sp.color||'#111111',font:data.action?.font||data.sp.font||'Helvetica'};if(editorState.selectedAction!==null){const a=editorState.actions[editorState.selectedAction];if(a?.type==='add_text')return {size:Number(a.size||14),color:a.color||'#111111',font:a.font||'Helvetica'};}return {size:14,color:'#111111',font:'Helvetica'};}
function editorTextContextToolbar(){const data=editorSelectedData(),add=editorState.selectedAction!==null?editorState.actions[editorState.selectedAction]:null;if(editorState.mode!=='select'||(!data&&add?.type!=='add_text'))return '';const st=selectedTextStyle(),flags=editorFontFlags(st.font),family=/times|serif/i.test(st.font)?'Times':/courier|mono/i.test(st.font)?'Courier':'Helvetica';return `<div class="editor-context-bar"><button type="button" class="format-toggle ${flags.bold?'active':''}" data-editor-format="bold" title="Bold"><b>B</b></button><button type="button" class="format-toggle ${flags.italic?'active':''}" data-editor-format="italic" title="Italic"><i>I</i></button><select id="editorFontFamily" aria-label="Font"><option value="Helvetica" ${family==='Helvetica'?'selected':''}>Arial</option><option value="Times" ${family==='Times'?'selected':''}>Times</option><option value="Courier" ${family==='Courier'?'selected':''}>Courier</option></select><input id="editorFontSize" type="number" min="5" max="90" value="${Math.round(st.size)}" aria-label="Font size"><input id="editorColor" type="color" value="${/^#[0-9a-f]{6}$/i.test(st.color)?st.color:'#111111'}" aria-label="Text color"><button type="button" class="context-delete" data-editor-command="delete-text">Delete</button><span class="context-tip">Click text and type directly</span></div>`;}
function signatureFontStack(style='script'){if(style==='elegant')return "'Monotype Corsiva','Segoe Script','Brush Script MT',cursive";if(style==='hand')return "'Lucida Handwriting','Segoe Print','Segoe Script',cursive";if(style==='bold')return "'Brush Script MT','Segoe Script',cursive";return "'Segoe Script','Brush Script MT','Monotype Corsiva',cursive";}
function signatureStyleLabel(style){return ({script:'Classic',elegant:'Elegant',hand:'Natural',bold:'Bold'})[style]||'Classic';}
function closeSignatureMaker(){qs('.signature-maker-backdrop')?.remove();signaturePlacement=null;}
function signatureDataURL(text,style,color){const canvas=document.createElement('canvas');canvas.width=1400;canvas.height=360;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);const family=signatureFontStack(style);let size=170;ctx.font=`${style==='bold'?'700 ':'400 '}${size}px ${family}`;let width=ctx.measureText(text).width;while(width>1240&&size>70){size-=6;ctx.font=`${style==='bold'?'700 ':'400 '}${size}px ${family}`;width=ctx.measureText(text).width;}ctx.fillStyle=color||'#0a3d9e';ctx.textBaseline='middle';ctx.fillText(text,70,185);return {data:canvas.toDataURL('image/png'),ratio:1400/360};}
function openSignatureMaker(point,page){closeSignatureMaker();signaturePlacement={point,page};const wrap=document.createElement('div');wrap.className='signature-maker-backdrop';wrap.innerHTML=`<div class="signature-maker" role="dialog" aria-modal="true" aria-label="Create signature"><button type="button" class="signature-close" data-signature-close>×</button><h3>Create your signature</h3><p>Type your name and choose a handwritten style.</p><label class="signature-name-label">Your name<input id="signatureNameInput" type="text" autocomplete="name" placeholder="Type your name"></label><div class="signature-style-grid">${['script','elegant','hand','bold'].map((st,i)=>`<button type="button" class="signature-style ${i===0?'active':''}" data-signature-style="${st}" style="font-family:${signatureFontStack(st)}"><span class="signature-style-preview">Signature</span><small>${signatureStyleLabel(st)}</small></button>`).join('')}</div><div class="signature-maker-foot"><label>Color <input id="signatureColorInput" type="color" value="#0a3d9e"></label><button type="button" class="signature-create-btn" data-signature-create disabled>Use signature</button></div></div>`;document.body.appendChild(wrap);const input=id('signatureNameInput'),create=qs('[data-signature-create]',wrap);let chosen='script';const refresh=()=>{const value=input.value.trim();qsa('.signature-style-preview',wrap).forEach(x=>x.textContent=value||'Signature');create.disabled=!value;};input.addEventListener('input',refresh);qsa('[data-signature-style]',wrap).forEach(b=>b.addEventListener('click',()=>{chosen=b.dataset.signatureStyle;qsa('[data-signature-style]',wrap).forEach(x=>x.classList.toggle('active',x===b));}));qs('[data-signature-close]',wrap).addEventListener('click',closeSignatureMaker);wrap.addEventListener('click',e=>{if(e.target===wrap)closeSignatureMaker();});create.addEventListener('click',()=>{const text=input.value.trim();if(!text||!signaturePlacement)return;const color=id('signatureColorInput')?.value||'#0a3d9e';const png=signatureDataURL(text,chosen,color);const p=signaturePlacement.page,pt=signaturePlacement.point;const w=Math.min(240,p.width-pt[0]-4),h=Math.min(w/png.ratio,p.height-pt[1]-4);if(w>20&&h>10)editorAddAction({type:'image',rect:[pt[0],pt[1],pt[0]+w,pt[1]+h],data:png.data,signature:true,signatureName:text});closeSignatureMaker();});requestAnimationFrame(()=>input.focus());}
function editorToolbar(){const tools=[['select','Text','T'],['image','Images','▧'],['signature','Sign','✍'],['whiteout','Whiteout','◇'],['highlight','Highlight','▰'],['draw','Annotate','✎'],['rectangle','Shapes','▭'],['pan','Hand','✋']];return `<div class="simple-editor-bar"><div class="simple-editor-tools">${tools.map(([m,l,i])=>`<button type="button" class="simple-tool ${editorState.mode===m?'active':''}" data-editor-mode="${m}" title="${l}"><span>${i}</span><b>${l}</b></button>`).join('')}</div><div class="simple-editor-actions"><button type="button" class="simple-icon-btn" data-editor-command="undo" ${editorState.actions.length?'':'disabled'} title="Undo">↶</button><div class="simple-page-nav"><button type="button" data-editor-command="prev" ${editorState.page===0?'disabled':''}>‹</button><span>${editorState.page+1} / ${editorState.pages.length}</span><button type="button" data-editor-command="next" ${editorState.page>=editorState.pages.length-1?'disabled':''}>›</button></div><div class="simple-zoom"><button type="button" data-editor-command="zoom-out">−</button><span id="editorZoomValue">${Math.round(editorState.zoom||100)}%</span><button type="button" data-editor-command="zoom-in">+</button><button type="button" data-editor-command="zoom-fit">Fit</button></div><button type="button" class="simple-save-btn" data-editor-command="save">Apply changes</button></div></div>${editorTextContextToolbar()}<input id="editorImageInput" class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp">`;}
function editorThumbsHTML(){return editorState.pages.map((pg,i)=>`<button type="button" class="editor-thumb ${i===editorState.page?'active':''}" data-editor-page="${i}" title="Page ${i+1}"><img loading="lazy" src="/api/editor/${encodeURIComponent(editorState.id)}/page/${i+1}.png" alt="Page ${i+1} thumbnail"><span>${i+1}</span></button>`).join('');}
function renderEditor(opts={}){const preview=id('filePreview');const p=editorCurrentPage();if(!preview||!p||!editorState.id)return;const oldShell=id('editorCanvasShell');const keepX=opts.resetScroll?0:(oldShell?.scrollLeft||0),keepY=opts.resetScroll?0:(oldShell?.scrollTop||0);preview.hidden=false;preview.classList.add('editor-active');id('workspaceView')?.classList.add('editor-loaded');const extracted=(p.text||[]).map((sp,i)=>editorSpanHTML(sp,i,p)).join('');const overlays=editorState.actions.map((a,i)=>editorActionHTML(a,p,i)).join('');const baseW=Math.round(p.width*EDITOR_PX_PER_PT),baseH=Math.round(p.height*EDITOR_PX_PER_PT),factor=(Number(editorState.zoom)||100)/100;const noText=!p.text?.length;preview.innerHTML=`<div class="simple-editor-head"><div><strong>${esc(editorState.name||'PDF')}</strong><span>${editorState.actions.length?`${editorState.actions.length} unsaved change${editorState.actions.length===1?'':'s'}`:(noText?'No editable text detected':`${(p.text||[]).length} editable text boxes`)}</span></div><a href="#tools" class="simple-back-link">Exit editor</a></div>${editorToolbar()}${noText?'<div class="editor-scan-note">No selectable text found. This looks like a scanned/image PDF. Run OCR first, then open the OCR PDF here.</div>':''}<div class="editor-app-body"><aside class="editor-thumbs" aria-label="PDF pages">${editorThumbsHTML()}</aside><div class="editor-center"><div class="editor-canvas-shell mode-${editorState.mode}" id="editorCanvasShell"><div class="editor-stage-sizer" id="editorStageSizer" style="width:${baseW*factor}px;height:${baseH*factor}px"><div class="editor-stage" id="editorStage" style="width:${baseW}px;height:${baseH}px;transform:scale(${factor})"><img class="editor-page" draggable="false" src="/api/editor/${encodeURIComponent(editorState.id)}/page/${editorState.page+1}/clean.png" alt="Editable PDF page ${editorState.page+1}"><div class="editor-text-layer ${editorState.mode==='select'?'enabled':''}">${extracted}</div>${overlays}</div></div></div></div><aside class="editor-right"><h3>Edit PDF</h3><div class="editor-info-box"><strong>${noText?'OCR required':'Direct text editing'}</strong>${noText?'This page has no selectable text. Use OCR first for scanned PDFs.':'Choose Text, then click existing text and type directly. Use the toolbar for images, whiteout, highlights, drawing and shapes.'}</div><button type="button" class="editor-save-side" data-editor-command="save">Save changes →</button></aside></div>`;wireEditorStage();requestAnimationFrame(()=>{const shell=id('editorCanvasShell');if(shell){shell.scrollLeft=keepX;shell.scrollTop=keepY;}const target=opts.focusSpan!==undefined?qs(`[data-editor-span="${opts.focusSpan}"]`,id('editorStage')):opts.focusAction!==undefined?qs(`[data-editor-action="${opts.focusAction}"]`,id('editorStage')):null;if(target){target.focus();if(opts.caretEnd){const r=document.createRange();r.selectNodeContents(target);r.collapse(false);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(r);}}});}
function openEditorShell(){const workspace=id('workspaceView'),preview=id('filePreview');workspace?.classList.add('editor-loaded','has-files');if(preview){preview.hidden=false;preview.classList.add('editor-active');}id('selectedSection').hidden=true;id('errorBox').hidden=true;id('progressBox').hidden=true;window.scrollTo({top:0,behavior:'instant'});}
function renderEditorLoading(file){openEditorShell();const preview=id('filePreview');preview.innerHTML=`<div class="editor-gate"><div class="editor-gate-card"><div class="editor-spinner"></div><h2>Opening PDF…</h2><p>${esc(file?.name||'PDF')} is being prepared for editing.</p><span>Reading pages and extracting editable text.</span></div></div>`;}
function renderEditorPasswordGate(file,message='This PDF is password-protected. Enter its password to edit it.',invalid=false){openEditorShell();editorPendingFile=file;const preview=id('filePreview');preview.innerHTML=`<div class="editor-gate"><div class="editor-gate-card password"><div class="editor-lock-icon">🔒</div><h2>Password required</h2><p>${esc(file?.name||'This PDF')} is protected.</p><div class="editor-password-field"><input id="editorPasswordInput" type="password" autocomplete="current-password" placeholder="Enter PDF password" aria-label="PDF password"><button type="button" data-editor-password-toggle title="Show or hide password">👁</button></div><div class="editor-password-message ${invalid?'bad':''}">${esc(message)}</div><button type="button" class="editor-password-submit" data-editor-password-submit>Unlock & edit PDF</button><button type="button" class="editor-gate-cancel" data-editor-command="cancel-open">Choose another PDF</button><small>Your password is used only to unlock this local editing session.</small></div></div>`;requestAnimationFrame(()=>id('editorPasswordInput')?.focus());}
function renderEditorOpenError(file,message){openEditorShell();editorPendingFile=file;const preview=id('filePreview');preview.innerHTML=`<div class="editor-gate"><div class="editor-gate-card"><div class="editor-lock-icon error">!</div><h2>Could not open PDF</h2><p>${esc(message||'The PDF could not be prepared for editing.')}</p><button type="button" class="editor-password-submit" data-editor-command="cancel-open">Choose another PDF</button></div></div>`;}
async function prepareEditor(file,password=''){if(!file)return;editorPendingFile=file;editorState.preparing=true;renderEditorLoading(file);id('processBtn').disabled=true;try{const fd=new FormData();fd.append('file',file,file.name);if(password)fd.append('password',password);const r=await fetch('/api/editor/prepare',{method:'POST',body:fd});let data={};try{data=await r.json();}catch{}if(!r.ok){if(data.password_required){editorState.preparing=false;renderEditorPasswordGate(file,data.error||'Enter the PDF password to continue.',!!data.invalid_password);return;}throw new Error(data.error||`HTTP ${r.status}`);}editorPendingFile=null;editorState={id:data.editor_id,name:data.name||file.name,pages:data.pages||[],page:0,actions:[],mode:'select',selectedSpan:null,selectedAction:null,pendingImage:null,preparing:false,zoom:100};renderEditor({resetScroll:true});requestAnimationFrame(()=>fitEditorWidth(false));showToast(data.pages?.[0]?.text?.length?`${data.pages?.[0]?.text?.length||0} text boxes extracted — click text and type directly.`:'No editable text found. OCR is needed for scanned PDFs.');}catch(err){editorState.preparing=false;renderEditorOpenError(file,err.message||'Could not prepare PDF editor.');}}
function setEditorZoom(value,{center=true}={}){const next=Math.max(25,Math.min(500,Math.round(Number(value)||100)));const shell=id('editorCanvasShell'),stage=id('editorStage'),sizer=id('editorStageSizer'),p=editorCurrentPage();if(!stage||!sizer||!p){editorState.zoom=next;return;}let ratioX=.5,ratioY=.15;if(shell&&center){const oldMaxX=Math.max(1,sizer.scrollWidth-shell.clientWidth),oldMaxY=Math.max(1,sizer.scrollHeight-shell.clientHeight);ratioX=oldMaxX>1?shell.scrollLeft/oldMaxX:.5;ratioY=oldMaxY>1?shell.scrollTop/oldMaxY:.15;}editorState.zoom=next;const factor=next/100,baseW=Math.round(p.width*EDITOR_PX_PER_PT),baseH=Math.round(p.height*EDITOR_PX_PER_PT);stage.style.transform=`scale(${factor})`;sizer.style.width=`${baseW*factor}px`;sizer.style.height=`${baseH*factor}px`;const label=id('editorZoomValue');if(label)label.textContent=`${next}%`;if(shell&&center)requestAnimationFrame(()=>{const newMaxX=Math.max(0,sizer.scrollWidth-shell.clientWidth),newMaxY=Math.max(0,sizer.scrollHeight-shell.clientHeight);shell.scrollLeft=newMaxX*ratioX;shell.scrollTop=newMaxY*ratioY;});}
function changeEditorZoom(delta){setEditorZoom((Number(editorState.zoom)||100)+delta);}
function fitEditorWidth(center=false){const shell=id('editorCanvasShell'),p=editorCurrentPage();if(!shell||!p)return;const baseW=p.width*EDITOR_PX_PER_PT;const available=Math.max(220,shell.clientWidth-36);setEditorZoom(Math.floor(available/baseW*100),{center});}
function editorPoint(e,stage){const p=editorCurrentPage();const r=stage.getBoundingClientRect();return [Math.max(0,Math.min(p.width,(e.clientX-r.left)/r.width*p.width)),Math.max(0,Math.min(p.height,(e.clientY-r.top)/r.height*p.height))];}
function editorAddAction(a){editorState.actions.push({...a,page:editorState.page});editorState.selectedSpan=null;editorState.selectedAction=editorState.actions.length-1;renderEditor({focusAction:a.type==='add_text'?editorState.selectedAction:undefined,caretEnd:true});}
function selectEditorSpan(index){const p=editorCurrentPage();if(!p?.text?.[index])return;editorState.selectedSpan={page:editorState.page,index};editorState.selectedAction=null;renderEditor({focusSpan:index});}
function selectEditorAction(index){const a=editorState.actions[index];if(!a||a.page!==editorState.page||a.type!=='add_text')return;editorState.selectedSpan=null;editorState.selectedAction=index;editorState.mode='select';renderEditor({focusAction:index});}
